record.field:
submission_model = env['x_hr.applicant_required_document_submission'].sudo()

def reflect_submission_state_to_checklist_line(rec):
    line = rec.x_line_id
    if not line or line.x_status in ('accepted', 'not_applicable'):
        return

    if rec.x_state == 'submitted':
        line.sudo().write({
            'x_status': 'submitted',
        })
        return

    if rec.x_state == 'rejected':
        note = line.x_notes or ''
        reason = rec.x_reviewer_note or 'Submission classified by the Marsellia writeback gateway as incomplete or requiring resubmission.'
        if reason and reason not in note:
            note = (note + '\n\nResubmission note: ' + reason).strip()

        line.sudo().write({
            'x_status': 'resubmission_requested',
            'x_notes': note,
        })
        return


for rec in records.sudo():
    values = {}

    line = rec.x_line_id
    checklist = rec.x_checklist_id or (line.x_checklist_id if line else False)
    applicant = rec.x_applicant_id or (checklist.x_applicant_id if checklist else False)
    document_type = (line.x_document_type_id if line else False) or rec.x_document_type_id

    if applicant and rec.x_applicant_id != applicant:
        values['x_applicant_id'] = applicant.id

    if checklist and rec.x_checklist_id != checklist:
        values['x_checklist_id'] = checklist.id

    # The checklist line controls the document type. This prevents conflict
    # between selected line and manually selected type.
    if document_type and rec.x_document_type_id != document_type:
        values['x_document_type_id'] = document_type.id

    document_code = False
    if line and line.x_document_code:
        document_code = line.x_document_code
    elif document_type and document_type.x_code:
        document_code = document_type.x_code

    if document_code and rec.x_document_code != document_code:
        values['x_document_code'] = document_code

    if not rec.x_source:
        values['x_source'] = 'manual'

    if not rec.x_state:
        values['x_state'] = 'submitted'

    if not rec.x_submitted_by_user_id:
        values['x_submitted_by_user_id'] = env.user.id

    if not rec.x_submitted_on and rec.create_date:
        values['x_submitted_on'] = rec.create_date

    if applicant and checklist and line:
        siblings = submission_model.search([
            ('x_applicant_id', '=', applicant.id),
            ('x_checklist_id', '=', checklist.id),
            ('x_line_id', '=', line.id),
        ], order='id asc')

        sequence = 1
        if rec.id in siblings.ids:
            sequence = siblings.ids.index(rec.id) + 1
        else:
            sequence = submission_model.search_count([
                ('x_applicant_id', '=', applicant.id),
                ('x_checklist_id', '=', checklist.id),
                ('x_line_id', '=', line.id),
                ('id', '<', rec.id),
            ]) + 1

        if rec.x_submission_sequence != sequence:
            values['x_submission_sequence'] = sequence

        document_label = False
        if document_type:
            document_label = (
                document_type.x_name_ar
                or document_type.x_name_en
                or document_type.x_name
                or document_type.display_name
            )
        if not document_label and line:
            document_label = (
                line.x_document_name_ar
                or line.x_document_name_en
                or line.x_name
                or line.display_name
            )
        if not document_label:
            document_label = 'المستند المطلوب'

        normalized_name = '%s / تقديم #%s' % (
            document_label,
            sequence,
        )

        if rec.x_name != normalized_name:
            values['x_name'] = normalized_name

    elif not rec.x_name:
        values['x_name'] = 'تقديم مستند مطلوب'

    if values:
        rec.sudo().write(values)

    rec = rec.sudo().browse(rec.id)
    reflect_submission_state_to_checklist_line(rec)

