checklist_model = env['x_hr.applicant_required_document_checklist'].sudo()
submission_model = env['x_hr.applicant_required_document_submission'].sudo()
request_model = env['x_hr.applicant_required_document_submission_request'].sudo()
request_line_model = env['x_hr.applicant_required_document_submission_request_line'].sudo()

for applicant in records.sudo():
    applicant_name = applicant.partner_name or applicant.name or applicant.display_name or 'Applicant'

    checklists = checklist_model.search([
        ('x_applicant_id', '=', applicant.id),
    ], order='id asc')

    for checklist_index, checklist in enumerate(checklists, start=1):
        reference = checklist.x_document_reference or ('MCEP-HR-F-0003-%05d-%02d' % (applicant.id, checklist_index))
        normalized_checklist_name = 'قائمة #%s' % checklist_index

        checklist_values = {}

        if checklist.x_checklist_sequence != checklist_index:
            checklist_values['x_checklist_sequence'] = checklist_index

        if not checklist.x_document_reference:
            checklist_values['x_document_reference'] = reference

        if checklist.x_name != normalized_checklist_name:
            checklist_values['x_name'] = normalized_checklist_name

        if checklist_values:
            checklist.sudo().write(checklist_values)

    submissions = submission_model.search([
        ('x_applicant_id', '=', applicant.id),
    ], order='x_checklist_id asc, x_line_id asc, id asc')

    for submission in submissions:
        line = submission.x_line_id
        checklist = submission.x_checklist_id or (line.x_checklist_id if line else False)
        document_type = (line.x_document_type_id if line else False) or submission.x_document_type_id

        submission_values = {}

        if checklist and submission.x_checklist_id != checklist:
            submission_values['x_checklist_id'] = checklist.id

        if document_type and submission.x_document_type_id != document_type:
            submission_values['x_document_type_id'] = document_type.id

        document_code = False
        if line and line.x_document_code:
            document_code = line.x_document_code
        elif document_type and document_type.x_code:
            document_code = document_type.x_code

        if document_code and submission.x_document_code != document_code:
            submission_values['x_document_code'] = document_code

        if not submission.x_source:
            submission_values['x_source'] = 'manual'

        if not submission.x_state:
            submission_values['x_state'] = 'submitted'

        if not submission.x_submitted_by_user_id:
            submission_values['x_submitted_by_user_id'] = env.user.id

        if not submission.x_submitted_on and submission.create_date:
            submission_values['x_submitted_on'] = submission.create_date

        if checklist and line:
            siblings = submission_model.search([
                ('x_applicant_id', '=', applicant.id),
                ('x_checklist_id', '=', checklist.id),
                ('x_line_id', '=', line.id),
            ], order='id asc')

            sequence = 1
            if submission.id in siblings.ids:
                sequence = siblings.ids.index(submission.id) + 1

            if submission.x_submission_sequence != sequence:
                submission_values['x_submission_sequence'] = sequence

            document_label = False
            if document_type:
                document_label = (
                    document_type.x_name_ar
                    or document_type.x_name_en
                    or document_type.x_name
                    or document_type.display_name
                )

            if not document_label and line:
                document_label = (
                    line.x_document_name_ar
                    or line.x_document_name_en
                    or line.x_name
                    or line.display_name
                )

            if not document_label:
                document_label = 'المستند المطلوب'

            normalized_submission_name = '%s / تقديم #%s' % (
                document_label,
                sequence,
            )

            if submission.x_name != normalized_submission_name:
                submission_values['x_name'] = normalized_submission_name

        elif not submission.x_name:
            submission_values['x_name'] = 'تقديم مستند مطلوب'

        if submission_values:
            submission.sudo().write(submission_values)

    requests = request_model.search([
        ('x_applicant_id', '=', applicant.id),
    ], order='id asc')

    for request_index, request in enumerate(requests, start=1):
        request_values = {}

        if request.x_sequence != request_index:
            request_values['x_sequence'] = request_index

        if not request.x_request_reference:
            request_values['x_request_reference'] = 'MCEP-HR-F-0003-REQ-%05d' % request.id

        normalized_request_name = '%s / طلب #%s' % (
            applicant_name,
            request_index,
        )

        if request.x_name != normalized_request_name:
            request_values['x_name'] = normalized_request_name

        if request_values:
            request.sudo().write(request_values)

        request_lines = request_line_model.search([
            ('x_request_id', '=', request.id),
        ], order='x_sequence asc, id asc')

        for request_line in request_lines:
            document_label = False

            if request_line.x_document_type_id:
                document_label = (
                    request_line.x_document_type_id.x_name_ar
                    or request_line.x_document_type_id.x_name_en
                    or request_line.x_document_type_id.x_name
                    or request_line.x_document_type_id.display_name
                )

            if not document_label and request_line.x_checklist_line_id:
                document_label = (
                    request_line.x_checklist_line_id.x_document_name_ar
                    or request_line.x_checklist_line_id.x_document_name_en
                    or request_line.x_checklist_line_id.x_name
                    or request_line.x_checklist_line_id.display_name
                )

            if not document_label:
                document_label = request_line.x_document_code or 'المستند المطلوب'

            normalized_line_name = 'طلب #%s / %s' % (
                request_index,
                document_label,
            )

            if request_line.x_name != normalized_line_name:
                request_line.sudo().write({
                    'x_name': normalized_line_name,
                })

    applicant.message_post(
        body='تم توحيد أسماء القائمة وطلبات التقديم وبنود الطلبات والمستندات المقدمة.'
    )

action = False
applicant = records[:1].sudo() if records else False
if applicant:
    checklist = checklist_model.search([
        ('x_applicant_id', '=', applicant.id),
        ('x_state', 'not in', ['cancelled']),
    ], order='id desc', limit=1)

    if checklist:
        view = env.ref('hr_recruitment_custom.view_required_document_checklist_form_controlled', raise_if_not_found=False)
        action = {
            'type': 'ir.actions.act_window',
            'name': checklist.x_name or 'Required Document Checklist',
            'res_model': 'x_hr.applicant_required_document_checklist',
            'res_id': checklist.id,
            'view_mode': 'form',
            'target': 'current',
            'context': dict(env.context, mcep_return_tab='documents'),
        }
        if view:
            action['views'] = [(view.id, 'form')]
    else:
        view = env.ref('hr_recruitment_custom.hr_applicant_form_inherit_mcep_custom', raise_if_not_found=False)
        action = {
            'type': 'ir.actions.act_window',
            'name': applicant.display_name or 'Applicant',
            'res_model': 'hr.applicant',
            'res_id': applicant.id,
            'view_mode': 'form',
            'target': 'current',
            'context': dict(env.context, mcep_return_tab='submissions'),
        }
        if view:
            action['views'] = [(view.id, 'form')]
else:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}
